    where (nullif(trim(MEMBER_NO),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__CUSTOMER_ID))) as HUB_PARTY_HK
        , INSURANCE_COMPANY as PARTY_FULL_NAME
