        , PATIENT_NAME as PARTY_FULL_NAME
        , GENDER as GENDER_CODE
        , DATE_OF_BIRTH as DATE_OF_BIRTH
        , AGE_IN_YEARS as AGE
        , cast(null as varchar) as FIRST_NAME
        , cast(null as varchar) as MIDDLE_NAME
        , cast(null as varchar) as LAST_NAME
        , cast(null as varchar) as PARTY_LEGAL_NAME
        , cast(null as varchar) as SALUTATION
        , cast(null as varchar) as PARTY_TYPE_CODE
        , cast(null as varchar) as PARTY_DISPLAY_NAME
        , cast(null as varchar) as PARTY_SUB_TYPE_CODE
        , cast(null as varchar) as PARTY_STATUS
        , cast(null as varchar) as PARTY_STATUS_REASON
        , 'BJAZ_HM_PREAUTH_REQUEST' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_preauth_request') }}
    where (nullif('HOSPID:' || nullif(trim(HOS_ID),''), 'HOSPID:')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__CUST_ID))) as HUB_PARTY_HK
        , NOMINEENAME as PARTY_FULL_NAME
        , GENDER as GENDER_CODE
        , DOB as DATE_OF_BIRTH
        , NOMINEEAGE as AGE
        , cast(null as varchar) as FIRST_NAME
        , cast(null as varchar) as MIDDLE_NAME
        , cast(null as varchar) as LAST_NAME
        , cast(null as varchar) as PARTY_LEGAL_NAME
        , cast(null as varchar) as SALUTATION
        , cast(null as varchar) as PARTY_TYPE_CODE
        , cast(null as varchar) as PARTY_DISPLAY_NAME
        , cast(null as varchar) as PARTY_SUB_TYPE_CODE
        , cast(null as varchar) as PARTY_STATUS
        , cast(null as varchar) as PARTY_STATUS_REASON
        , 'BJAZ_PMSBY_DATA_WEB_SERVICE' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_pmsby_data_web_service') }}
    where (nullif(trim(CUST_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__INTERMEDIARY_ID))) as HUB_PARTY_HK
        , INTERMEDIARY_NAME as PARTY_FULL_NAME
        , cast(null as varchar) as GENDER_CODE
        , cast(null as varchar) as DATE_OF_BIRTH
        , cast(null as varchar) as AGE
        , cast(null as varchar) as FIRST_NAME
        , cast(null as varchar) as MIDDLE_NAME
        , cast(null as varchar) as LAST_NAME
        , cast(null as varchar) as PARTY_LEGAL_NAME
        , cast(null as varchar) as SALUTATION
        , cast(null as varchar) as PARTY_TYPE_CODE
        , cast(null as varchar) as PARTY_DISPLAY_NAME
        , cast(null as varchar) as PARTY_SUB_TYPE_CODE
        , cast(null as varchar) as PARTY_STATUS
        , cast(null as varchar) as PARTY_STATUS_REASON
        , 'BJAZ_INTERMEDIARY' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_intermediary') }}
    where (nullif(trim(INTERMEDIARY_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PARTNER_ID))) as HUB_PARTY_HK
        , CUSTOMER_NAME_TEXT as PARTY_FULL_NAME
        , cast(null as varchar) as GENDER_CODE
        , cast(null as varchar) as DATE_OF_BIRTH
        , cast(null as varchar) as AGE
        , cast(null as varchar) as FIRST_NAME
        , cast(null as varchar) as MIDDLE_NAME
        , cast(null as varchar) as LAST_NAME
        , cast(null as varchar) as PARTY_LEGAL_NAME
        , cast(null as varchar) as SALUTATION
        , cast(null as varchar) as PARTY_TYPE_CODE
        , cast(null as varchar) as PARTY_DISPLAY_NAME
        , cast(null as varchar) as PARTY_SUB_TYPE_CODE
        , cast(null as varchar) as PARTY_STATUS
        , cast(null as varchar) as PARTY_STATUS_REASON
        , 'OCP_INTERESTED_PARTIES' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ocp_interested_parties') }}
    where (nullif('PARTNER:' || nullif(trim(PARTNER_ID),''), 'PARTNER:')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__user_name))) as HUB_PARTY_HK
        , cust_name as PARTY_FULL_NAME
        , cast(null as varchar) as GENDER_CODE
        , cast(null as varchar) as DATE_OF_BIRTH
        , cast(null as varchar) as AGE
        , cast(null as varchar) as FIRST_NAME
        , cast(null as varchar) as MIDDLE_NAME
        , cast(null as varchar) as LAST_NAME
        , cast(null as varchar) as PARTY_LEGAL_NAME
        , cast(null as varchar) as SALUTATION
        , cast(null as varchar) as PARTY_TYPE_CODE
        , cast(null as varchar) as PARTY_DISPLAY_NAME
        , cast(null as varchar) as PARTY_SUB_TYPE_CODE
        , cast(null as varchar) as PARTY_STATUS
        , cast(null as varchar) as PARTY_STATUS_REASON
        , 'BJAZ_BOT_UTILIZATION_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_bot_utilization_dtls') }}
    where (md5(normalise(upper(nullif(trim(user_name),''))))) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__contract_id_first_name_middle_name_last_name_date_of_birth))) as HUB_PARTY_HK
        , nominee_name as PARTY_FULL_NAME
        , gender as GENDER_CODE
        , date_of_birth as DATE_OF_BIRTH
        , age as AGE
        , first_name as FIRST_NAME
        , middle_name as MIDDLE_NAME
        , last_name as LAST_NAME
        , cast(null as varchar) as PARTY_LEGAL_NAME
        , cast(null as varchar) as SALUTATION
        , cast(null as varchar) as PARTY_TYPE_CODE
        , cast(null as varchar) as PARTY_DISPLAY_NAME
        , cast(null as varchar) as PARTY_SUB_TYPE_CODE
        , cast(null as varchar) as PARTY_STATUS
        , cast(null as varchar) as PARTY_STATUS_REASON
        , 'BA_CCP_INSURED_DETAILS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ba_ccp_insured_details') }}
    where (md5(normalise(upper(nullif(coalesce(nullif(trim(contract_id),''),'') || '|INSURED|' || coalesce(nullif(trim(first_name),''),'') || '|' || coalesce(nullif(trim(middle_name),''),'') || '|' || coalesce(nullif(trim(last_name),''),'') || '|' || coalesce(nullif(trim(to_char(date_of_birth)),''),''), '|INSURED||||'))))) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__MEMBER_NO))) as HUB_PARTY_HK
        , cast(null as varchar) as PARTY_FULL_NAME
        , GENDER as GENDER_CODE
        , DOB as DATE_OF_BIRTH
        , AGE_YEAR as AGE
        , FIRST_NAME as FIRST_NAME
        , MIDDLE_NAME as MIDDLE_NAME
        , LAST_NAME as LAST_NAME
        , cast(null as varchar) as PARTY_LEGAL_NAME
        , cast(null as varchar) as SALUTATION
        , cast(null as varchar) as PARTY_TYPE_CODE
        , cast(null as varchar) as PARTY_DISPLAY_NAME
        , cast(null as varchar) as PARTY_SUB_TYPE_CODE
        , cast(null as varchar) as PARTY_STATUS
        , cast(null as varchar) as PARTY_STATUS_REASON
        , 'BJAZ_REMEDINET_PATIENT_DETAILS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_remedinet_patient_details') }}
    where (nullif('MEMBER:' || nullif(trim(MEMBER_NO),''), 'MEMBER:')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__CONTRACT_ID_INSURED_NAME))) as HUB_PARTY_HK
        , INSURED_NAME as PARTY_FULL_NAME
        , cast(null as varchar) as GENDER_CODE
        , cast(null as varchar) as DATE_OF_BIRTH
        , cast(null as varchar) as AGE
        , cast(null as varchar) as FIRST_NAME
        , cast(null as varchar) as MIDDLE_NAME
        , cast(null as varchar) as LAST_NAME
        , cast(null as varchar) as PARTY_LEGAL_NAME
        , cast(null as varchar) as SALUTATION
        , cast(null as varchar) as PARTY_TYPE_CODE
        , cast(null as varchar) as PARTY_DISPLAY_NAME
        , cast(null as varchar) as PARTY_SUB_TYPE_CODE
        , cast(null as varchar) as PARTY_STATUS
        , cast(null as varchar) as PARTY_STATUS_REASON
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (md5(normalise(upper(nullif(coalesce(nullif(trim(CONTRACT_ID),''),'') || '|INSURED|' || coalesce(nullif(trim(INSURED_NAME),''),''), '|INSURED|'))))) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then PARTY_FULL_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PARTY_FULL_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then PARTY_FULL_NAME end)) as PARTY_FULL_NAME,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then GENDER_CODE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then GENDER_CODE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then GENDER_CODE end)) as GENDER_CODE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then DATE_OF_BIRTH end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DATE_OF_BIRTH end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then DATE_OF_BIRTH end)) as DATE_OF_BIRTH,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then AGE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AGE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then AGE end)) as AGE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FIRST_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then FIRST_NAME end)) as FIRST_NAME,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MIDDLE_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then MIDDLE_NAME end)) as MIDDLE_NAME,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LAST_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then LAST_NAME end)) as LAST_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PARTY_LEGAL_NAME end) as PARTY_LEGAL_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SALUTATION end) as SALUTATION,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PARTY_TYPE_CODE end) as PARTY_TYPE_CODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PARTY_DISPLAY_NAME end) as PARTY_DISPLAY_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PARTY_SUB_TYPE_CODE end) as PARTY_SUB_TYPE_CODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PARTY_STATUS end) as PARTY_STATUS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PARTY_STATUS_REASON end) as PARTY_STATUS_REASON,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when PARTY_FULL_NAME is not null or GENDER_CODE is not null or DATE_OF_BIRTH is not null or AGE is not null or FIRST_NAME is not null or MIDDLE_NAME is not null or LAST_NAME is not null or PARTY_LEGAL_NAME is not null or SALUTATION is not null or PARTY_TYPE_CODE is not null or PARTY_DISPLAY_NAME is not null or PARTY_SUB_TYPE_CODE is not null or PARTY_STATUS is not null or PARTY_STATUS_REASON is not null
                     then md5(upper(coalesce(cast(PARTY_FULL_NAME as varchar), '') || '|' || coalesce(cast(GENDER_CODE as varchar), '') || '|' || coalesce(cast(DATE_OF_BIRTH as varchar), '') || '|' || coalesce(cast(AGE as varchar), '') || '|' || coalesce(cast(FIRST_NAME as varchar), '') || '|' || coalesce(cast(MIDDLE_NAME as varchar), '') || '|' || coalesce(cast(LAST_NAME as varchar), '') || '|' || coalesce(cast(PARTY_LEGAL_NAME as varchar), '') || '|' || coalesce(cast(SALUTATION as varchar), '') || '|' || coalesce(cast(PARTY_TYPE_CODE as varchar), '') || '|' || coalesce(cast(PARTY_DISPLAY_NAME as varchar), '') || '|' || coalesce(cast(PARTY_SUB_TYPE_CODE as varchar), '') || '|' || coalesce(cast(PARTY_STATUS as varchar), '') || '|' || coalesce(cast(PARTY_STATUS_REASON as varchar), '')))
                end as SAT_PARTY_IDENTITY_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_IDENTITY_HASHDIFF is not null
